content.text:
The root cause is ts-travel-service CPU saturation, and its slowdown reaches users through route-plan, travel-plan and preserve. ts-voucher-service restarted, but no span or metric in the data links it to any caller or user path, so I left it out.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT 'normal' p, metric, round(avg(value),3) avg_v, round(max(value),3) max_v FROM normal_metrics WHERE service_name='ts-travel-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2 UNION ALL SELECT 'abnormal', metric, round(avg(value),3), round(max(value),3) FROM abnormal_metrics WHERE service_name='ts-travel-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu_limit_utilization') GROUP BY 1,2",
          "claim": "ts-travel-service container CPU rose from about 0.18 to 0.97 cores on average, peaking at 4.6, with CPU-limit utilization reaching 0.95."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abnormal' p, metric, round(avg(value),4) avg_v, round(max(value),4) max_v FROM abnormal_metrics WHERE service_name='ts-travel-service' AND metric IN ('jvm.cpu.recent_utilization','container.cpu.usage') GROUP BY 1,2",
          "claim": "JVM recent CPU utilization stays near 0.002 while container CPU is high, so the load sits in the container rather than the JVM alone."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelservice/trips/left' GROUP BY 1,2 UNION ALL SELECT 'normal', span_name, count(*), approx_quantile(duration,0.95)/1e6 FROM normal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelservice/trips/left' GROUP BY 1,2",
          "claim": "ts-travel-service's own trips/left server span p95 rose from about 464 ms to about 1440 ms, with no error increase."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, s.service_name callee, substr(s.span_name,1,60) sn, count(*) n, approx_quantile(p.duration,0.95)/1e6 cli_p95, approx_quantile(s.duration,0.95)/1e6 srv_p95 FROM abnormal_traces p JOIN abnormal_traces s ON s.trace_id=p.trace_id AND s.parent_span_id=p.span_id WHERE p.service_name='ts-route-plan-service' AND p.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY 1,2,3",
          "claim": "Route-plan's client calls into ts-travel-service slow to about 1.3 s p95 at the travel-service server; route-plan POSTs also fail with 503 after about 480 ms."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, span_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, sum(case when attr_status_code='Error' then 1 else 0 end) errs FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Route-plan's quickest/cheapest route server spans are slow, with p95 around 1.2 to 3.2 s and some 500 errors, against sub-second in normal."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, substr(span_name,1,70) sn, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, sum(case when attr_status_code='Error' then 1 else 0 end) errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelPlan%' GROUP BY 1,2",
          "claim": "User-facing ui-dashboard travelPlan requests slow to 3 to 6 s p95 in the abnormal period; normal is far lower."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, s.service_name callee, substr(s.span_name,1,60) sn, count(*) n, approx_quantile(p.duration,0.95)/1e6 cli_p95 FROM abnormal_traces p JOIN abnormal_traces s ON s.trace_id=p.trace_id AND s.parent_span_id=p.span_id WHERE p.service_name='ts-preserve-service' AND p.attr_span_kind='Client' AND s.service_name='ts-travel-service' GROUP BY 1,2,3",
          "claim": "Preserve's client calls to ts-travel-service slow to over 1.6 s p95 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, substr(span_name,1,70) sn, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%preserve%' GROUP BY 1,2",
          "claim": "User-facing ui-dashboard preserve requests reach about 2.3 s p95, against about 0.3 s median, after travel-service slowed."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abnormal' p, substr(span_name,1,70) sn, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms, sum(case when attr_status_code='Error' then 1 else 0 end) errs FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE '%travelservice/trips/left%' GROUP BY 1,2",
          "claim": "User-facing ui-dashboard trips/left requests reach about 3.6 s p95 with 15 errors, against much lower latency in normal."
        }
      ]
    }
  ]
}
```

